yotsuba.css:
/** GENERIC / ELEMENT STYLING **/
html {
	-moz-text-size-adjust: 100%;
	-webkit-text-size-adjust: 100%;
	-ms-text-size-adjust: 100%;
}

body {
	background: #FFFFEE url(/image/fade.png) top center repeat-x;

	color: #800000;
	font-family: arial, helvetica, sans-serif;
	font-size: 10pt;

	margin-left: 0;
	margin-right: 0;
	margin-top: 5px;

	padding-left: 5px;
	padding-right: 5px;
}

.nwsb { display: none; }

.adg-rects {
  margin: 0;
  text-align: center;
}
.adg, .adg-m { overflow: hidden; }
.adg-rep .adg { margin-left: 15px }
.adp-228 { margin: auto; width: 728px; height: 320px; }
.adp-90 { margin: auto; width: 728px; height: 90px; }
.adp-128 { margin: auto; width: 728px; height: 128px; }
.adp-j { margin: auto; width: 728px; height: 102px; }
.adp-50 { margin: auto; width: 320px; height: 50px; }
.adp-250 { margin: auto; width: 300px; height: 250px; }
.adp-row { display: inline-block; margin: 0 10px; }
.adl { font-size: 10px; text-align: center; }
.adl + .ad-bgls, .ad-bgls + .adl { margin-top: 8px; }

.danbo-slot { width: 728px; height: 90px; margin: 10px auto; overflow: hidden; }
@media only screen and (max-width: 480px) { .danbo-slot { width: 300px; height: 250px; } }

.bsa-cnt {
  margin: 20px 0;
  height: 90px;
  text-align: center;
}

#t-root {
  overflow: hidden;
  box-sizing: border-box;
  background: #eee;
  border: 1px solid #777;
  margin: 2px 0 2px 0;
  width: 300px;
}

@media only screen and (max-width: 640px) {
  .bsa-cnt {
    height: 250px;
    display: flex;
    justify-content: center;
    align-items: center;
  }
}

.adc-resp {
  margin: auto;
  width: 728px;
  height: 228px;
  overflow: hidden;
}

.adc-resp-bg {
  margin: auto;
  width: 728px;
  height: 112px;
  overflow: hidden;
}

@media only screen and (max-width: 480px) {
  .adc-resp {
    width: 300px;
    height: 300px;
  }
  
  #quickReply {
    z-index: 9000 !important;
  }
  
  .adc-resp-bg {
    width: 300px;
    height: 250px;
  }
}

hr#op, #ctrl-top { clear: both; }

.party-hat {
  left: 0;
  margin-top: -80px;
  position: absolute;
  pointer-events: none;
}

.sjis, #quickReply .sjis {
  font-size: 16px;
  line-height: 17px;
  white-space: pre;
  font-family: 'IPAMonaPGothic', 'Mona', 'MS PGothic', monospace;
  overflow: auto;
  display: block;
  clear: left;
}

.tex-logo { font-size: 0.8em; }
.tex-logo sub { font-size: 0.8em; text-transform: uppercase; }

.mu-s { font-weight: bold }
.mu-i { font-style: italic }
.mu-r { color: #C41E3A }
.mu-g { color: #00A550 }
.mu-b { color: #1d8dc4 }

.pu-lbl {
  color: #117743;
  font-weight: bold;
  font-size: 12px;
}
.pu-img {
  vertical-align: middle;
  margin-top: -3px;
  margin-right: 3px;
  display: inline-block;
  width: 16px;
  height: 16px;
  background: url('//s.4cdn.org/image/minileaf.gif');
}

.n-pu {
  vertical-align: middle;
  display: inline-block;
  width: 16px;
  height: 16px;
  margin-top: -2px;
  background: url('//s.4cdn.org/image/minileaf.gif');
}

.jla-it {
  height: 420px;
  width: 680px;
}

.jla-it-p {
  font-size: 0.85em;
  text-align: center;
}

.n-atb {
  border-radius: 6px;
  padding: 1px 4px;
  color: #353839;
}

.atsb2018 table {
  margin: auto;
  font-size: 90%;
}
.atsb2018 td {
  white-space: nowrap;
  padding: 0px 4px;
}
.atsb2018 .atsgc {
  width: 280px;
}
.atsb2018 .atgg {
  height: 20px;
}

.n-atb-0 { background-color: #F56FA1; }
.n-atb-1 { background-color: #7B3F00; color: #F2F3F4; }
.n-atb-2 { background-color: #FFFDD0; }
.n-atb-3 { background-color: #E4D00A; }
.n-atb-4 { background-color: #50C878; }

.n-atb-0::after { content: 'Team Peep'; }
.n-atb-1::after { content: 'Team Chocolate'; }
.n-atb-2::after { content: 'Team Creme'; }
.n-atb-3::after { content: 'Team Peanut Butter'; }
.n-atb-4::after { content: 'Team Mini'; }

@media only screen and (max-width: 700px) {
  .jla-it {
    width: 340px;
    height: 220px;
    margin: auto;
  }
  
  .jla-it img {
    width: 340px;
    height: 200px;
  }
}

.centeredThreads .party-hat {
  left: 12%;
}

#disclaimer {
  font-size: 14px;
  position: absolute;
  overflow: hidden;
  top: 0; left: 0;
  width: 100%; height: 100%;
  z-index: 9998;
}

#disclaimer-bg {
  position: fixed;
  top: 0; left: 0;
  width: 100%; height: 100%;
  background-color: rgba(0, 0, 0, 0.25);
}

#disclaimer-modal {
  z-index: 9999;
  width: 320px;
  top: 0;
  left: 50%;
  margin-left: -170px;
  display: block;
  padding: 10px;
  position: relative;
  background-color: #f0e0d6;
  box-shadow: 0 0 5px rgba(0, 0, 0, 0.25);
}

#disclaimer ol {
  margin-left: 20px;
  padding: 0;
}

#disclaimer li {
  margin: 10px 0;
}

#disclaimer h3 {
  border-bottom: 1px solid #d9bfb7;
  margin: 0;
  padding-bottom: 5px;
  text-align: center;
}

#disclaimer-modal div {
  margin-top: 10px;
  text-align: center;
}

#disclaimer-modal button {
  margin: 0 10px;
}

#disclaimer-accept {
  font-weight: bold;
}

#footer-links { margin-top: 5px; }

.isMobileDevice blockquote.postMessage {
  font-size: 11pt;
}

.belowLeaderboard {
  width: 728px;
  max-width: 100%;
}

.aboveMidAd {
  width: 468px;
  max-width: 100%;
}

/* reCaptcha */
#captchaContainerAlt { height: 80px; }
#captchaContainerAlt .recaptcha_image_cell { padding: 0 0 5px 0 !important }
#captchaContainerAlt #recaptcha_table { border: 0 !important; }
#captchaContainerAlt #recaptcha_response_field { width: 300px !important; padding: 0 !important }

#qrCaptchaContainerAlt #recaptcha_response_field {
  width: 296px !important;
}

#captchaContainerAlt #recaptcha_image,
#qrCaptchaContainerAlt #recaptcha_image {
  border: 0 !important;
}

#qrCaptchaContainerAlt .recaptcha_image_cell {
  padding: 0 !important;
}

#qrCaptchaContainerAlt #recaptcha_table {
  border: 0 !important;
}

#captchaContainerAlt td:nth-child(2),
#captchaContainerAlt td:nth-child(3),
#qrCaptchaContainerAlt td:nth-child(2),
#qrCaptchaContainerAlt td:nth-child(3) {
  display: none !important;
}

#qrCaptchaContainerAlt {
  height: 80px;
  width: 300px;
}

.recaptchatable {
  background-color: transparent !important;
  border: none !important;
}

.recaptcha_image_cell {
	background-color: transparent !important;
}

#g-recaptcha {
  height: 78px;
}

#recaptcha_div {
  height: 107px; width: 442px;
}

#recaptcha_challenge_field { width: 400px }

.recaptcha_input_area {
	padding: 0!important;
}
#recaptcha_table tr:first-child {
	height: auto!important;
}

#recaptcha_table tr:first-child > td:not(:first-child) {
	padding: 0 7px 0 7px!important;
}

#recaptcha_table tr:last-child td:last-child {
	padding-bottom: 0!important;
}

#recaptcha_table tr:last-child td:first-child {
	padding-left: 0!important;
}
#recaptcha_image {
	cursor: pointer;
}
#recaptcha_response_field {
	width: 292px;
	margin-right: 0px!important;
	font-size: 10pt!important;
}
input:-moz-placeholder { color: gray !important; }
#recaptcha_image {
	border: 1px solid #aaa !important;
}
#recaptcha_table tr > td:last-child {
	display: none !important;
}
#captchaContainer {
  width: 343px;
  height: 86px;
  line-height: 99px;
  overflow: hidden;
}
#captchaContainer .placeholder {
  font-style: italic;
  padding-left: 5px;
}

.mobile, .mobileinline, .mobileib {
	display: none !important;
}

a, a:visited {
	color: #00E;
	text-decoration: none;
}

a.replylink:not(:hover), div#absbot a:not(:hover) {
	color: #00E !important;
}

a:hover {
	color: red !important;
}

div#absbot {
	color: #800000;
	clear: both;
}

div.board > hr {
	clear: both;
}

img {
	border: none;
}

img.topad, .topad > div, .topad a img {
	width: 728px;
	height: 90px;
	max-width: 100%;
	overflow: hidden;
	margin: auto;
}

img.middlead, .middlead > div, .middlead a img{
	width: 468px;
	height: 60px;
	max-width: 100%;
	overflow: hidden;
	margin: auto;
}

img.bottomad, .bottomad > div, .bottomad a img {
	width: 728px;
	height: 90px;
	max-width: 100%;
	overflow: hidden;
	margin: auto;
}

hr {
	border: none;
	border-top: 1px solid #D9BFB7;

	height: 0;
}

hr.abovePostForm {
	width: 90%;
}

span.x-small {
	font-size: x-small;
}

#postFormError {
  background-color: #e62020;
  color: #fff;
  font-family: monospace;
  font-size: 13px;
  font-weight: bold;
  padding: 3px 5px;
  text-shadow: 0 1px rgba(0, 0, 0, 0.2);
  display: none;
  margin-top: 3px;
}

#postFormError a {
  color: #fff;
}

.painter-ctrl input[type="text"],
#qr-painter-ctrl input[type="text"] {
  width: 30px !important;
  text-align: center;
}

#qr-painter-ctrl .oe-r-cb {
  vertical-align: sub;
}

#oe-canvas-preview {
  position: absolute;
  margin-left: 5px;
  margin-top: 3px;
  box-shadow: 0 0 1px 1px rgba(0, 0, 0, 0.25);
}

/** MOBILE ONLY DISABLES **/
.mobile {
	display: none;
}

/** HEADER **/
ul.rules {
  margin: 0px;
  padding: 0px;
  margin-top: 5px;
}

ul.rules > li {
  list-style: none;
  font-size: 11px;
}

.rules > li:before {
	content: "\2022 \20";
}

div.boardBanner {
	text-align: center;
	clear: both;
}

#bannerCnt {
	border: 1px solid #800;
	margin: 5px auto;
	width: 300px;
	height: 100px;
	max-width: 100%;
}

div.boardBanner > div.boardTitle {
	font-family: Tahoma, sans-serif;
	font-size: 28px;
	font-weight: bold;
	letter-spacing: -2px;

	margin-top: 0px;
}

div.boardBanner > div.boardSubtitle {
	font-size: x-small;
}

div#boardNavDesktop {
	font-size: 9pt;
	color: #B86;
	display: block;
}

.hasDropDownNav #navtopright {
  display: none;
}

#boardNavDesktop .pageJump {
  padding: 0;
}

#boardNavDesktop .pageJump a {
  padding-right: 5px;
}

div#boardNavDesktop a {
	font-weight: normal;
	padding: 1px;
	text-decoration: none;
	color: #800000;
}

/** General Containers **/
div.pContainer {

}

div.opContainer {
	display: inline;
}

div.sideArrows {
	color: #e0bfb7;

	float: left;

	margin-right: 2px;
	margin-top: 0px;
	margin-left: 2px;
}

/** Thread Container **/
div.thread {

	margin: 0px;
	clear: both;

}

/** Post Container **/
div.post {
	margin: 4px 0;
	overflow: hidden;
}

div.thread > div:nth-of-type(2) > div.reply {
	margin-top: 2px !important;
}

div.op {
	display: inline;
}

div.reply {
	background-color: #f0e0d6;

	border: 1px solid #D9BFB7;
	border-left: none;
	border-top: none;

	display: table;

	padding: 2px;
}

div.reply input {
	float: none;
}

/** Post Information **/
div.post div.postInfo {
	display: block;
	width: 100%;
}

.fileText {
  max-width: 600px;
  white-space: nowrap;
}

div.post div.postInfo span.postNum {

}

div.post div.postInfo span.postNum a {
	text-decoration: none;
	color: #800000;
}

div.post div.postInfo span.postNum a:hover, .posteruid .hand:hover {
	color: red !important;
}

/* Name */
div.post div.postInfo span.nameBlock {
	display: inline-block;
}

div.post div.postInfo span.nameBlock span.name {
	color: #117743;
	font-weight: bold;
}

div.post div.postInfo span.nameBlock span.postertrip {
	color: #117743;
	font-weight: normal !important;
}

/* Date/Time */
div.post div.postInfo span.date {

}

div.post div.postInfo span.time {

}

/* Subject */
div.post div.postInfo span.subject {
	color: #cc1105;
	font-weight: bold;
}

/** Message **/
div.post blockquote.postMessage {
	display: block;
}

blockquote > span.quote {
	color: #789922;
}

.quoteLink, .quotelink, .deadlink, .pageJump a {
	color: #000080 !important;
	text-decoration: underline;
}

.pageJump a:hover {
	color: #ff0000 !important;
}

/* Archived threads list */
.is_arclist .belowLeaderboard { display: none; }

#arc-list {
  max-width: 80%;
  margin: 10px auto 0 auto;
}

#arc-list td {
  text-align: center;
}

#arc-list .teaser-col {
  text-align: left;
  word-break: break-all;
}

#arc-list .quotelink {
  color: #34345C !important;
}

#arc-list .quotelink:hover {
  color: #D00 !important;
}

#arc-sort {
  border-bottom: 1px dotted;
  cursor: pointer;
}

/** File Information **/
div.post div.file {
	display: block;
}

div.post div.file div.fileInfo {
	margin-right: 10px;
  word-break: break-all;
}

div.replyContainer div.post div.file div.fileInfo {
	margin-left: 20px;
}

div.post div.file .fileThumb {
	float: left;
	margin-left: 20px;
	margin-right: 20px;
	margin-top: 3px;
	margin-bottom: 5px;
}

span.fileThumb {
	margin-left: 0px !important;
	margin-right: 5px !important;
}

div.reply span.fileThumb, div.reply span.fileThumb img {
	float: none !important;
	margin-top: 0px !important;
	margin-bottom: 0px !important;
}

div.post div.file .fileThumb img {
	border: none;

	float: left;
}

/** Summary **/
span.summary {
	color: #707070;
	margin-top: 10px;
}

/** POST FORM **/
div.postingMode {
	background-color: #e04000;
	padding: 1px;
	text-align: center;

	color: #fff;
	font-weight: bold;
	font-size: larger;

	margin-top: 8px;
}

#verification table {
	border: none !important;
	margin: 0px;
}

/** FOOTER **/
div.thread:last-child {
	padding-bottom: 21px;
	margin-bottom: 6px;

}

div.pagelist {
	font-size: 13px !important;

	margin: 0;
	padding: 3px 7px;

	float: left;

	border: none;
	background: #F0E0D6;

	border-right: 1px solid #D9BFB7;
	border-bottom: 1px solid #D9BFB7;

	list-style: none;
	overflow: hidden;

	color: #B86;
}

div.pagelist > div {
	float: left;
}

div.pagelist > div span {
	padding: 4px;
	display: inline-block;
}

div.pagelist div.pages {
	padding: 4px;
}

div.pagelist div.pages a {
	text-decoration: none !important;
	/* FINE MOOT GOSH JEEZ */
}

div.pagelist form {
	display: inline;
}

div.pagelist strong {
	color: #800000;
}

div.pagelist div.cataloglink {
	border-left: 1px solid #D9BFB7;
	padding-left: 12px;
	margin-left: 7px;
}

.bottomCtrl {
  float: right;
  margin-top: 2px;
}

input[type=password] {
	width: 50px;
	text-align: center;
}

div.deleteform input[type=checkbox] {
	margin: 1px 2px 1px 2px;
}

.stylechanger {
	margin-left: 5px;
	font-size: 10pt;
}

div#boardNavDesktopFoot {
	font-size: 9pt;
	color: #B86;

	clear: both;

	padding-top: 10px;
	padding-bottom: 3px;
}

div#boardNavDesktopFoot a {
	font-weight: normal;
	padding: 1px;
	text-decoration: none;
	color: #800000;
}

div.homelink {
	float: right
}

div#absbot {
	text-align: center;
	font-size: x-small !important;

	padding-bottom: 4px;
	padding-top: 10px;

	color: #800;
}

#recaptcha_response_field {
	padding: 0px;
}

/** POST FORM **/
table {
	border-spacing: 1px;

	margin-left: auto;
	margin-right: auto;
}

table.postForm > tbody > tr > td:first-child {
	background-color: #EA8;
	color: #800;
	font-weight: bold;
	border: 1px solid #800;
	padding: 0 5px;

	font-size: 10pt;
}

tr.rules td {
	border: 0px !important;
	background-color: transparent !important;
	font-weight: normal !important;
}

td {
	margin: 0px;
	padding: 0px;

	font-size: 10pt;
}

input[type=text], input[type=password], table.postForm > tbody textarea, #recaptcha_response_field {
	margin: 0px;
	margin-right: 2px;
	padding: 2px 4px 3px 4px;

	border: 1px solid #AAA;
	outline: none;

	font-family: arial, helvetica, sans-serif;
	font-size: 10pt;
}

#recaptcha_response_field:not(:focus) {
	border: 1px solid #AAA !important;
}

input[type=text]:focus, input[type=password]:focus, input:not([type]):focus, textarea:focus {
	border: 1px solid #ea8 !important;
}

table.postForm > tbody > tr > td > input[type=text] {
	width: 244px;
}

table.postForm > tbody > tr > td > input[name="subject"] {
	width: 300px;
}

.postblock {
	background-color: #EA8;
	color: #800;
	font-weight: bold;
	border: 1px solid #800;
	padding: 0 5px;
	font-size: 10pt;
}

div.closed {
	font-size: x-large;
	text-align: center;
	color: red;
	font-weight: bold;

	padding-top: 100px;
	padding-bottom: 100px;
}

.arc-ads {
  width: 300px;
  margin: 30px auto -60px auto;
}

.arc-ads::after {
  display: block;
  content: '';
  clear: both;
}

@media screen and (-webkit-min-device-pixel-ratio:0) {
	tbody textarea {
		margin-bottom: -3px !important;
		width: 292px
	}
}

.commentpostername {
	font-weight: bold;
}

.identityIcon {
	margin-bottom: -3px;
	height: 16px;
	width: 16px;
}

.stickyIcon {
	margin-bottom: -1px;
	padding-left: 2px;
	height: 16px;
	width: 16px;
}

.archivedIcon,
.closedIcon {
	margin-bottom: -1px;
	margin-left: -1px;
	height: 16px;
	width: 16px;
}

.trashIcon {
	width: 16px;
	height: 16px;
	margin-bottom: -2px;
}

.fileDeleted {
	height: 13px;
	width: 172px;
}

.fileDeletedRes {
	height: 13px;
	width: 127px;
}

.navSmall {
	font-size: 90%;
}

.center {
	text-align: center;
}

.bold {
	font-weight: bold;
}

.smaller {
	font-size: smaller;
}

.password {
	font-size: smaller;
}

.passNotice {
	font-size: smaller;
	padding-left: 6px;
}

.qcDiv {
	display: none;
}

.qcImg {
	height: 1px;
	width: 1px;
	border: 0px;
}

.jpnFlag {
	height: 11px;
	width: 17px;
}

.globalMessage {
	color: red;
	text-align: center;
}

.highlightPost:not(.op) {
	background: #f0d6d6 !important;
	border-color: #d69595 !important;
}

.reply:target, .reply.highlight {
	background: #F0C0B0 !important;
	border: 1px solid #D99F91 !important;
	border-left: none !important;
	border-top: none !important;
	padding: 2px;
}

.hand {
	cursor: pointer;
}

.nameBlock.capcodeAdmin span.name, span.capcodeAdmin a span.name, span.capcodeAdmin span.postertrip, span.capcodeAdmin strong.capcode {
	color: #F00 !important;
}

span.capcodeFounder span.name, span.capcodeFounder span.name a, span.capcodeFounder span.postertrip, span.capcodeFounder strong.capcode {
	color: #117743 !important;
}

.nameBlock.capcodeMod span.name, span.capcodeMod a span.name, span.capcodeMod span.postertrip, span.capcodeMod strong.capcode {
	color: #800080 !important;
}

.nameBlock.capcodeDeveloper span.name, span.capcodeDeveloper a span.name, span.capcodeDeveloper span.postertrip, span.capcodeDeveloper strong.capcode {
	color: #0000F0 !important;
}

.nameBlock.capcodeManager span.name, span.capcodeManager a span.name, span.capcodeManager span.postertrip, span.capcodeManager strong.capcode {
	color: #FF0080 !important;
}

.nameBlock.capcodeVerified span.name, span.capcodeVerified span.name a, span.capcodeVerified span.postertrip, span.capcodeVerified strong.capcode {
  color: #007FFF !important;
}

#reportTypes a,
.useremail {
  text-decoration: underline;
}

.omittedposts, .abbr {
	color: #707070;
}

span.spoiler {
	color: #000 !important;
