/** Here's one for you: internet explorer in wp7 can only handle 1 stylesheet at a time it seems **/
/** Chrome Mobile seems to dislike media="" in html, so we do it this way instead. **/
@media only screen and (max-width: 480px) {
	/** GENERIC / ELEMENT STYLING **/
	html {
		-moz-text-size-adjust: 100%;
		-webkit-text-size-adjust: 100%;
		-ms-text-size-adjust: 100%;
	}
	
  .postMenuBtn {
    -webkit-transform: rotate(90deg);
    -moz-transform: rotate(90deg);
    -ms-transform: rotate(90deg);
    transform: rotate(90deg);
    margin: 4px -5px 0px 4px !important;
    float: left;
    font-weight: bold;
    opacity: 1 !important;
    height: 0.5em !important;
    font-size: 16px;
  }
  
  .dd-menu {
    font-size: 16px;
    line-height: 2.5em;
  }
  
  .adg-rects > span.mobile {
    display: inline-block !important;
  }
  
  .party-hat {
    left: -15px;
    margin-top: -30px;
    position: absolute;
    width: 100px;
    pointer-events: none;
  }
  
  .pu-img {
    background: url('//s.4cdn.org/image/minileaf@2x.gif');
    background-size: 100%;
  }
  
	body {
		background: #EEF2FF url(/image/fade-blue.png) top center repeat-x;

		color: #000000;
		font-family: arial, helvetica, sans-serif;
		font-size: 10pt;

		margin-left: 0;
		margin-right: 0;
		margin-top: 5px;

		padding-left: 0px;
		padding-right: 0px;

		width: 100%;
	}
	
